function confirm(prompt) {
  return new Promise((resolve4) => {
    const rl = readline2.createInterface({ input: process.stdin, output: process.stdout });
    rl.question(prompt, (answer) => {
      rl.close();
      resolve4(/^y(es)?$/i.test(answer.trim()));
    });
  });
}
